-- Paket ABT "abt-u4-dk-wali-perwalian" (agen U4, 20 Okt 2026): perwalian oleh kerabat, dispensasi kawin (alasan mendesak otomatis, dua keluarga Pemohon, Pasal 15/16 PERMA 5/2019, perbedaan usia), wali adhal (Pasal 21 dan 61 KHI, persetujuan calon, masa tunggu). 24 variabel baru 4400-4442, 3 blangko baru, 12 blangko lama diperbarui dengan penjaga md5.
-- PRASYARAT (baca saja) "A|B|C|D|E": A = nomor 4400-4442 milik paket yang berisi LAIN (harus 0) | B = yang sudah berisi persis paket (0 pertama, 24 ulang) | C = variabel lama yang dirujuk blangko ADA (harus 130) | D, E = 0.
-- Benar: "0|0|130|0|0" (pertama) atau "0|24|130|0|0" (pasang ulang).
SELECT CONCAT((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (4400,4401,4402,4403,4404,4405,4406,4407,4409,4410,4411,4412,4420,4421,4422,4423,4424,4425,4426,4427,4428,4440,4441,4442) AND NOT ((no_var=4400 AND MD5(nama)='2e0d20fae9e6e1fd2992edc16ff804f2' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4401 AND MD5(nama)='5aacd37ad6c60f52f44a38a9331cd547' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4402 AND MD5(nama)='6fb52b95fdc3af6cbb72e4707f0b282a' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4403 AND MD5(nama)='9dbe5d6261948cbe19624de4f1b2e8e3' AND data_type='data_tanggal' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4404 AND MD5(nama)='7dbacd0cb5b6363e4a1be496ccff572c' AND data_type='data_tanggal' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4405 AND MD5(nama)='667d9ee8fce6ae43e9a7d1423efa3642' AND data_type='data_sql' AND MD5(sql_query)='9874971761689c91a4e66da09ffc3c2a' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4406 AND MD5(nama)='d9ed65143b3511ffa60889e64822e12e' AND data_type='data_sql' AND MD5(sql_query)='0ff6121ef8050abc391ecbb96ddf63a1' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4407 AND MD5(nama)='9a6366de648cc3aea7cbe13279f174f3' AND data_type='data_sql' AND MD5(sql_query)='2b3d0aa1a29183bfc2060a52bf965deb' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4409 AND MD5(nama)='af30b8dca85f927d21036fc65bab97d9' AND data_type='data_sql' AND MD5(sql_query)='96cb0fb08a2f5531ed70b35f8c287da4' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4410 AND MD5(nama)='e02fbe5063d99c7d9913051c47c7a037' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4411 AND MD5(nama)='d66422ef1503f177d45324b20dba2292' AN