ensi IS NULL) OR (no_var=4440 AND MD5(nama)='806e289afe6d3729da5df626074b059f' AND data_type='data_sql' AND MD5(sql_query)='ab7ee34d2db90b6c1068130ac32f5457' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4441 AND MD5(nama)='291970da16dc375636799064693a2081' AND data_type='data_sql' AND MD5(sql_query)='f23f871975d1bac0433845adb4bdc42b' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4442 AND MD5(nama)='33cd38ea6b8e8104986262f6753f02f7' AND data_type='data_sql' AND MD5(sql_query)='36d3911c49408bde68fb0d9a0923abeb' AND default_data IS NULL AND referensi IS NULL))),'|',(SELECT COUNT(*) FROM abt_variabel WHERE (no_var=4400 AND MD5(nama)='2e0d20fae9e6e1fd2992edc16ff804f2' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4401 AND MD5(nama)='5aacd37ad6c60f52f44a38a9331cd547' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4402 AND MD5(nama)='6fb52b95fdc3af6cbb72e4707f0b282a' AND data_type='data_teks' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4403 AND MD5(nama)='9dbe5d6261948cbe19624de4f1b2e8e3' AND data_type='data_tanggal' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4404 AND MD5(nama)='7dbacd0cb5b6363e4a1be496ccff572c' AND data_type='data_tanggal' AND sql_query IS NULL AND default_data IS NULL AND referensi IS NULL) OR (no_var=4405 AND MD5(nama)='667d9ee8fce6ae43e9a7d1423efa3642' AND data_type='data_sql' AND MD5(sql_query)='9874971761689c91a4e66da09ffc3c2a' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4406 AND MD5(nama)='d9ed65143b3511ffa60889e64822e12e' AND data_type='data_sql' AND MD5(sql_query)='0ff6121ef8050abc391ecbb96ddf63a1' AND default_data IS NULL AND referensi IS NULL) OR (no_var=4407 AND MD5(nama)='9a6366de648cc3aea7cbe13279f174f3' AND data_type='data_sql' AND MD5(sql_query)='2b3d0aa1a29183bfc2060a52bf965deb' AND default_data IS NULL AN